<?php
if(!defined('INCLUDE_DIR')){http_response_code(404);exit;}
function dune_show_application_receipts(){return !empty($_SESSION['dune_show_applications']);}
function dune_application_ticket_ids(){static $ids;if(isset($ids))return $ids;require_once __DIR__.'/dune-ticket-identifiers.php';return $ids=array_map('intval',dune_identifier_db()->query("SELECT t.ticket_id FROM drsupport_ticket t JOIN drsupport_help_topic h ON h.topic_id=t.topic_id WHERE h.topic='Election application receipt'")->fetchAll(PDO::FETCH_COLUMN));}
function dune_filter_application_receipts($query){global $thisstaff;if(!$thisstaff||dune_show_application_receipts())return $query;$ids=dune_application_ticket_ids();return $ids?$query->exclude(['ticket_id__in'=>$ids]):$query;}
function dune_application_staff_visible($ticketId){return dune_show_application_receipts()||!in_array((int)$ticketId,dune_application_ticket_ids(),true);}
function dune_application_toggle_html(){global $ost;if(!$ost)return '';$token=$ost->getCSRFFormInput();return '<section class="dune-applications-toggle" style="padding:16px;margin:16px 0;border:1px solid #a68e49;border-radius:10px;background:#17392b"><form method="post" action="/scp/application-visibility.php">'.$token.'<label><input type="checkbox" name="show_applications" value="1"'.(dune_show_application_receipts()?' checked':'').'> Show application registration tickets</label> <button type="submit">Apply</button><p>Automatic election receipts are hidden from staff lists by default. This filter keeps normal department permissions; applicants can always view their own receipt.</p></form></section>';}
